css:
.authoritysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8edf4;
    background: linear-gradient(160deg, #11161f 0%, #1a2230 60%, #141b27 100%);
    border-radius: 18px;
}

.authoritysim-container * {
    box-sizing: border-box;
}

.authoritysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1d2738 0%, #243248 55%, #2c3c56 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #33425c;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.42);
}

.authoritysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.authoritysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0b35b;
    background: rgba(240, 179, 91, 0.12);
    border: 1px solid rgba(240, 179, 91, 0.35);
    padding: 5px 14px;
    border-radius: 999px;
}

.authoritysim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c4d0e0;
}

.authoritysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b6c4d8;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.authoritysim-period-counter #currentDay,
.authoritysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f0b35b;
}

.authoritysim-round-name {
    background: #2a3950;
    color: #f0b35b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #3a4d6b;
}

.authoritysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9d7a;
    background: rgba(255, 107, 74, 0.14);
    border: 1px solid rgba(255, 107, 74, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.authoritysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.authoritysim-status-card {
    background: #1c2532;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #2c3a4f;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.28);
    border-top: 4px solid #5a7290;
}

.authoritysim-card-trust { border-top-color: #f0b35b; }
.authoritysim-card-decision { border-top-color: #4fb0c8; }
.authoritysim-card-follower { border-top-color: #7ec98a; }
.authoritysim-card-self { border-top-color: #b08ad6; }

.authoritysim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea2bd;
}

.authoritysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
}

.authoritysim-card-trust .authoritysim-value { color: #f0b35b; }
.authoritysim-card-decision .authoritysim-value { color: #6fc6dc; }
.authoritysim-card-follower .authoritysim-value { color: #8ed99a; }
.authoritysim-card-self .authoritysim-value { color: #c5a3e6; }

.authoritysim-sublabel {
    font-size: 0.75rem;
    color: #8294ad;
    line-height: 1.35;
}

.authoritysim-trust-strong .authoritysim-value { color: #8ed99a; }
.authoritysim-trust-weak .authoritysim-value { color: #ff7a5c; }

.authoritysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    background: #0f1722;
    color: #dbe6f2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
    border: 1px solid #2c3a4f;
}

.authoritysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0b35b;
}

.authoritysim-risk {
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9d7a;
    background: rgba(255, 107, 74, 0.12);
    border: 1px solid rgba(255, 107, 74, 0.3);
    padding: 3px 12px;
    border-radius: 999px;
}

.authoritysim-budget-low #budgetDisplay { color: #ff7a5c; }

.authoritysim-briefing {
    display: flex;
    gap: 14px;
    background: #1c2532;
    border-left: 5px solid #f0b35b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #2c3a4f;
    border-left-width: 5px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
}

.authoritysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.authoritysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.authoritysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d0e0;
}

.authoritysim-briefing-text strong { color: #f0b35b; }
.authoritysim-briefing-text em { color: #ff9d7a; font-style: italic; }

.authoritysim-controls {
    background: #1c2532;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #2c3a4f;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
}

.authoritysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid #2c3a4f;
    padding-bottom: 8px;
}

.authoritysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d4deea;
    margin: 14px 0 6px;
}

.authoritysim-container select,
.authoritysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3a4d6b;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #131a25;
    color: #eef3f9;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.authoritysim-container select:focus,
.authoritysim-container input[type="number"]:focus {
    outline: none;
    border-color: #f0b35b;
    box-shadow: 0 0 0 3px rgba(240, 179, 91, 0.2);
}

.authoritysim-container select option {
    background-color: #131a25;
    color: #eef3f9;
}

.authoritysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f0b35b;
}

.authoritysim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb2cb;
    margin-top: 4px;
}

.authoritysim-range-readout span:last-child {
    color: #f0b35b;
    font-weight: 800;
}

.authoritysim-hint {
    font-size: 0.8rem;
    color: #8294ad;
    margin-top: 4px;
    line-height: 1.4;
}

.authoritysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.authoritysim-container .btn-primary {
    background: linear-gradient(135deg, #e0962f 0%, #f0b35b 100%);
    border: none;
    color: #1a1206;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 18px rgba(224, 150, 47, 0.32);
}

.authoritysim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.authoritysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #3a4d6b;
    color: #9fb2cb;
    background: transparent;
}

.authoritysim-coach {
    background: #0f1722;
    color: #dbe6f2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #2c3a4f;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
}

.authoritysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0b35b;
    margin-bottom: 8px;
}

.authoritysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.authoritysim-coach-body strong { color: #f0b35b; }
.authoritysim-coach-body em { color: #ff9d7a; font-style: italic; }

.authoritysim-history,
.authoritysim-chart {
    background: #1c2532;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #2c3a4f;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
}

.authoritysim-history h3,
.authoritysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.authoritysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d0e0;
}

.authoritysim-container table#usfHistoryTable th {
    background: #243248;
    color: #f0b35b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #33425c;
}

.authoritysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #2c3a4f;
}

.authoritysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #19212d;
}

.authoritysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .authoritysim-container {
        padding: 14px;
    }
    .authoritysim-header h1 {
        font-size: 1.7rem;
    }
    .authoritysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .authoritysim-value {
        font-size: 2rem;
    }
    .authoritysim-clock {
        margin-left: 0;
    }
    .authoritysim-period-counter {
        font-size: 0.88rem;
    }
    .authoritysim-budget-bar {
        flex-direction: column;
        align-items: flex-start;
    }
    .authoritysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.authoritysim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2230; }
.authoritysim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(26,34,48,0.15); margin-bottom: 16px; }
.authoritysim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #b06f12; }
.authoritysim-cm-score-max { font-size: 18px; font-weight: 600; color: #4b5b74; margin-left: 2px; }
.authoritysim-cm-grade { font-size: 18px; font-weight: 700; color: #1a2230; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.authoritysim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.authoritysim-cm-yes { background: rgba(31,122,77,0.15); color: #175d40; }
.authoritysim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.authoritysim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.authoritysim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.authoritysim-cm-metric { flex: 1 1 120px; background: #eef1f6; border: 1px solid rgba(26,34,48,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.authoritysim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #1a2230; }
.authoritysim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #4b5b74; margin-top: 2px; }
.authoritysim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #4b5b74; margin-bottom: 8px; }
.authoritysim-cm-insights { margin: 0; padding-left: 20px; }
.authoritysim-cm-insights li { font-size: 14px; line-height: 1.5; color: #26314a; margin-bottom: 8px; }

