(function() {
    'use strict';

    class AuthorityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Earning Authority`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Voltaris Systèmes SAS).
            this.HELIOS_SIZE = 11;
            this.REVENUE_AT_RISK = 3.2;        // EUR millions if the freeze slips
            this.FREEZE_DAYS = 5;              // working days to Friday 19 June
            this.CREDIBILITY_CAP = 100;        // fragile credibility capital
            this.TRUST_TARGET = 70;            // squad has clearly granted authority

            // Starting KPIs — deliberately LOW, with headroom through round 4.
            this.START_TRUST = 20;
            this.START_DECISION = 25;
            this.START_FOLLOWER = 18;
            this.START_SELF = 22;

            // Concept truths.
            this.TRUE_SOURCE = `earned`;
            this.TRUE_READ = `needs`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: this.START_TRUST,
                    decision: this.START_DECISION,
                    follower: this.START_FOLLOWER,
                    self: this.START_SELF,
                    credibility: this.CREDIBILITY_CAP,
                    rankPulled: false,
                    abdicated: false,
                    freezeMade: false,
                    contractSet: false,
                    trustHistory: [this.START_TRUST],
                    decisionHistory: [this.START_DECISION],
                    followerHistory: [this.START_FOLLOWER],
                    selfHistory: [this.START_SELF],
                    credibilityHistory: [this.CREDIBILITY_CAP],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    source: `earned`,
                    read: `needs`,
                    humility: 55,
                    response: `merits`,
                    stance: `calibrated`,
                    safety: 55,
                    frame: `consent`,
                    approach: `acknowledge`,
                    role: 55,
                    process: `surface`,
                    director: `honest`,
                    contract: `explicit`,
                    resolve: 65
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const src = document.getElementById(`sourceInput`);
                const rd = document.getElementById(`readInput`);
                const hum = document.getElementById(`humilityInput`);
                if (src) decisions.source = src.value;
                if (rd) decisions.read = rd.value;
                if (hum) decisions.humility = parseInt(hum.value, 10);
                if (!Number.isFinite(decisions.humility) || decisions.humility < 0 || decisions.humility > 100) {
                    warn(`warn_humility_range`); return false;
                }
            } else if (round === 2) {
                const resp = document.getElementById(`responseInput`);
                const st = document.getElementById(`stanceInput`);
                const saf = document.getElementById(`safetyInput`);
                if (resp) decisions.response = resp.value;
                if (st) decisions.stance = st.value;
                if (saf) decisions.safety = parseInt(saf.value, 10);
                if (!Number.isFinite(decisions.safety) || decisions.safety < 0 || decisions.safety > 100) {
                    warn(`warn_safety_range`); return false;
                }
            } else if (round === 3) {
                const fr = document.getElementById(`frameInput`);
                const ap = document.getElementById(`approachInput`);
                const ro = document.getElementById(`roleInput`);
                if (fr) decisions.frame = fr.value;
                if (ap) decisions.approach = ap.value;
                if (ro) decisions.role = parseInt(ro.value, 10);
                if (!Number.isFinite(decisions.role) || decisions.role < 0 || decisions.role > 100) {
                    warn(`warn_role_range`); return false;
                }
            } else if (round === 4) {
                const pr = document.getElementById(`processInput`);
                const di = document.getElementById(`directorInput`);
                const co = document.getElementById(`contractInput`);
                const re = document.getElementById(`resolveInput`);
                if (pr) decisions.process = pr.value;
                if (di) decisions.director = di.value;
                if (co) decisions.contract = co.value;
                if (re) decisions.resolve = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.resolve) || decisions.resolve < 0 || decisions.resolve > 100) {
                    warn(`warn_resolve_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas across the four authority KPIs, plus credibility capital burn.
            let trustDelta = 0, decisionDelta = 0, followerDelta = 0, selfDelta = 0;
            let credBurn = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the SOURCE of authority (earned, not granted) — Key Concept 1.
                if (d.source === this.TRUE_SOURCE) {
                    trustDelta += 10; selfDelta += 8; coachKey = `coach_r1_earned`;
                } else if (d.source === `title`) {
                    trustDelta -= 6; selfDelta -= 6; credBurn += 6; coachKey = `coach_r1_title`;
                } else if (d.source === `director`) {
                    trustDelta -= 2; selfDelta -= 2; coachKey = `coach_r1_director`;
                } else {
                    trustDelta += 2; selfDelta -= 4; coachKey = `coach_r1_seniority`;
                }

                // Read the team — what each member needs to grant consent (Learning Teams).
                if (d.read === this.TRUE_READ) {
                    followerDelta += 10; decisionDelta += 8; selfDelta += 6;
                    if (d.source === this.TRUE_SOURCE) coachKey = `coach_r1_sharp`;
                } else if (d.read === `plan`) {
                    followerDelta -= 4; selfDelta -= 4; coachKey = `coach_r1_plan`;
                } else if (d.read === `architecture`) {
                    followerDelta -= 8; decisionDelta -= 2; coachKey = `coach_r1_arch`;
                } else {
                    followerDelta -= 10; selfDelta -= 6; credBurn += 4; coachKey = `coach_r1_allies`;
                }

                // Reflective honesty about what you don't yet know (Learning Teams premise).
                if (d.humility >= 50) { selfDelta += 6; followerDelta += 2; }
                else if (d.humility <= 20) { selfDelta -= 8; coachKey = `coach_r1_nohumility`; }

                summaryKey = (d.source === this.TRUE_SOURCE && d.read === this.TRUE_READ) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Answer the public challenge WITHOUT pulling rank or abdicating (Common Errors 1 & 2).
                switch (d.response) {
                    case `merits`:
                        trustDelta += 14; decisionDelta += 12; selfDelta += 4; coachKey = `coach_r2_merits`; break;
                    case `rank`:
                        trustDelta -= 14; decisionDelta -= 8; credBurn += 22; ds.rankPulled = true; coachKey = `coach_r2_rank`; break;
                    case `defer`:
                        trustDelta -= 8; decisionDelta -= 6; followerDelta -= 4; ds.abdicated = true; coachKey = `coach_r2_defer`; break;
                    case `dodge`:
                        trustDelta -= 6; decisionDelta -= 4; selfDelta -= 2; coachKey = `coach_r2_dodge`; break;
                }

                // Stance for the week — calibrating question vs direct (Key Concept 4).
                switch (d.stance) {
                    case `calibrated`:
                        trustDelta += 6; decisionDelta += 8; selfDelta += 4;
                        if (d.response === `merits`) coachKey = `coach_r2_calibrated`; break;
                    case `directive`:
                        trustDelta -= 4; decisionDelta -= 2; credBurn += 6; coachKey = (d.response === `rank`) ? coachKey : `coach_r2_directive`; break;
                    case `facilitative`:
                        decisionDelta -= 4; followerDelta -= 2; ds.abdicated = true; coachKey = (d.response === `defer`) ? coachKey : `coach_r2_facilitative`; break;
                }

                // Psychological safety set in week one (Key Concept 5).
                if (d.safety >= 55) { decisionDelta += 8; followerDelta += 6; }
                else if (d.safety <= 25) { decisionDelta -= 8; followerDelta -= 4; coachKey = `coach_r2_nosafety`; }

                summaryKey = (d.response === `merits` && d.stance === `calibrated`) ? `sum_r2_good` : ((d.response === `rank` || d.stance === `directive`) ? `sum_r2_rank` : `sum_r2_weak`);
            } else if (round === 3) {
                // Re-engage the veteran: withheld consent, NOT a performance problem (Common Error 3).
                switch (d.frame) {
                    case `consent`:
                        followerDelta += 12; trustDelta += 6; selfDelta += 4; coachKey = `coach_r3_consent`; break;
                    case `performance`:
                        followerDelta -= 16; trustDelta -= 8; credBurn += 12; coachKey = `coach_r3_performance`; break;
                    case `ignore`:
                        followerDelta -= 10; decisionDelta -= 6; coachKey = `coach_r3_ignore`; break;
                }

                // How you open the conversation — acknowledge honestly, don't over-promise or patronise.
                switch (d.approach) {
                    case `acknowledge`:
                        followerDelta += 10; trustDelta += 4; selfDelta += 2;
                        if (d.frame === `consent`) coachKey = `coach_r3_acknowledge`; break;
                    case `overpromise`:
                        followerDelta -= 6; trustDelta -= 6; credBurn += 8; coachKey = `coach_r3_overpromise`; break;
                    case `patronise`:
                        followerDelta -= 8; trustDelta -= 4; coachKey = `coach_r3_patronise`; break;
                }

                // A real, concrete role for her legacy-codebase expertise (the swing vote on the freeze).
                if (d.role >= 50) { followerDelta += 8; decisionDelta += 4; }
                else if (d.role <= 25) { followerDelta -= 6; coachKey = `coach_r3_norole`; }

                summaryKey = (d.frame === `consent` && d.approach === `acknowledge`) ? `sum_r3_good` : ((d.frame === `performance`) ? `sum_r3_discipline` : `sum_r3_weak`);
            } else if (round === 4) {
                // Run the freeze the way the culture demands, then own the call (Common Error 4).
                switch (d.process) {
                    case `surface`:
                        trustDelta += 14; decisionDelta += 14; followerDelta += 8; ds.freezeMade = true; coachKey = `coach_r4_surface`; break;
                    case `overquestion`:
                        decisionDelta -= 6; trustDelta -= 8; coachKey = `coach_r4_overquestion`; break;
                    case `impose`:
                        trustDelta -= 10; decisionDelta -= 8; credBurn += 14; ds.freezeMade = true; ds.rankPulled = true; coachKey = `coach_r4_impose`; break;
                }

                // Honest reflection vs performed confidence (Common Error 5 / Learning Teams).
                switch (d.director) {
                    case `honest`:
                        selfDelta += 12; trustDelta += 6; followerDelta += 4;
                        if (d.process === `surface`) coachKey = `coach_r4_honest`; break;
                    case `confidence`:
                        selfDelta -= 10; trustDelta -= 4; credBurn += 8; coachKey = `coach_r4_confidence`; break;
                    case `please`:
                        trustDelta -= 8; decisionDelta -= 6; selfDelta -= 4; coachKey = `coach_r4_please`; break;
                }

                // The explicit leadership contract that stabilises authority and prevents velocity collapse.
                switch (d.contract) {
                    case `explicit`:
                        trustDelta += 8; followerDelta += 6; decisionDelta += 4; ds.contractSet = true;
                        if (d.process === `surface` && d.director === `honest`) coachKey = `coach_r4_contract`; break;
                    case `implicit`:
                        trustDelta -= 4; followerDelta -= 4; coachKey = `coach_r4_implicit`; break;
                    case `control`:
                        trustDelta -= 10; followerDelta -= 8; credBurn += 10; coachKey = `coach_r4_control`; break;
                }

                // Resolve nudges self-awareness (holding the durable line under director pressure).
                selfDelta += Math.round((d.resolve - 55) / 9);

                summaryKey = (d.process === `surface` && d.director === `honest` && d.contract === `explicit`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Credibility capital is fragile: it only ever depletes (no top-up in five days).
            ds.credibility = Math.max(0, ds.credibility - credBurn);

            // A depleted credibility account drags trust and follower engagement — the fragile
            // constraint actually binds when you keep reaching for the badge.
            if (ds.credibility <= 40) { trustDelta -= 4; followerDelta -= 3; }

            // Apply KPI deltas (bounded 0–100; deliberate low start keeps headroom to round 4).
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.decision = Math.max(0, Math.min(100, ds.decision + decisionDelta));
            ds.follower = Math.max(0, Math.min(100, ds.follower + followerDelta));
            ds.self = Math.max(0, Math.min(100, ds.self + selfDelta));

            ds.trustHistory.push(Math.round(ds.trust));
            ds.decisionHistory.push(Math.round(ds.decision));
            ds.followerHistory.push(Math.round(ds.follower));
            ds.selfHistory.push(Math.round(ds.self));
            ds.credibilityHistory.push(Math.round(ds.credibility));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                decision: Math.round(ds.decision),
                decisionDelta: Math.round(decisionDelta),
                follower: Math.round(ds.follower),
                followerDelta: Math.round(followerDelta),
                self: Math.round(ds.self),
                selfDelta: Math.round(selfDelta),
                credibility: Math.round(ds.credibility),
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(valueMillions) {
