        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.trustHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                authorityChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory },
                        { data: ds.decisionHistory },
                        { data: ds.followerHistory },
                        { data: ds.selfHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var trust = Math.round(ds.trust || 0);
            var decision = Math.round(ds.decision || 0);
            var follower = Math.round(ds.follower || 0);
            var selfa = Math.round(ds.self || 0);
            return Math.round(trust * 0.32 + decision * 0.24 + follower * 0.24 + selfa * 0.20);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = Math.round(ds.trust);
            const decision = Math.round(ds.decision);
            const follower = Math.round(ds.follower);
            const selfa = Math.round(ds.self);

            const earned = trust >= this.TRUST_TARGET && follower >= 60;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_failed`;
            if (earned && selfa >= 55 && composite >= 72) performanceKey = `grade_earned`;
            else if (earned) performanceKey = `grade_thin`;
            else if (ds.rankPulled && trust < 45) performanceKey = `grade_forfeited`;
            else if (ds.abdicated && trust < 50) performanceKey = `grade_vacuum`;
            else if (trust > this.START_TRUST + 25) performanceKey = `grade_onway`;
            const performance = T(performanceKey);

            const insights = [];
            if (earned && selfa >= 55) insights.push(window.mySimulation.t(`insight_earned`));
            else if (ds.rankPulled) insights.push(window.mySimulation.t(`insight_rank`));
            else if (ds.abdicated) insights.push(window.mySimulation.t(`insight_abdicate`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (follower < 45) insights.push(window.mySimulation.t(`insight_lowfollower`));
            if (selfa < 40) insights.push(window.mySimulation.t(`insight_lowself`));
            if (!ds.contractSet) insights.push(window.mySimulation.t(`insight_nocontract`));
            if (ds.credibility <= 40) insights.push(window.mySimulation.t(`insight_credburn`));
            if (earned && ds.contractSet && selfa >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                trust: trust,
                decision: decision,
                follower: follower,
                self: selfa,
                earned: earned,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                rankPulled: ds.rankPulled,
                abdicated: ds.abdicated,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!s.earned;
            var badge = ok
                ? '<span class="authoritysim-cm-badge authoritysim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="authoritysim-cm-badge authoritysim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.rankPulled || s.abdicated)
                ? '<span class="authoritysim-cm-badge authoritysim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.trust || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_trust') + '</span></div>'
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.decision || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_decision') + '</span></div>'
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.follower || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_follower') + '</span></div>'
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.self || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_self') + '</span></div>';
            return ''
                + '<div class="authoritysim-completion">'
                +   '<div class="authoritysim-cm-head">'
                +     '<div class="authoritysim-cm-score">' + score + '<span class="authoritysim-cm-score-max">/100</span></div>'
                +     '<div class="authoritysim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="authoritysim-cm-metrics">' + metrics + '</div>'
                +   '<div class="authoritysim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="authoritysim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.rankPulled && state.currentPeriod >= 2) return window.mySimulation.t(`hint_rank`);
            if (ds.abdicated && state.currentPeriod >= 2) return window.mySimulation.t(`hint_abdicate`);
            if (ds.follower < 35) return window.mySimulation.t(`hint_follower`);
            if (ds.self < 35) return window.mySimulation.t(`hint_self`);
            if (state.currentPeriod >= 3 && ds.trust < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.trust >= this.TRUST_TARGET && ds.follower >= 60 && ds.self >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

